(()=>{'use strict';const sticky=document.querySelector('.sticky'),hero=document.querySelector('.hero'),offer=document.getElementById('oferta');let heroVisible=true,offerVisible=false;if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.target===hero)heroVisible=e.isIntersecting;else offerVisible=e.isIntersecting});sticky.classList.toggle('is-visible',!heroVisible&&!offerVisible)});observer.observe(hero);observer.observe(offer)}document.querySelectorAll('[data-checkout-pending]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();const status=document.getElementById('checkout-status');status.hidden=false;status.textContent='Checkout ainda não conectado. As compras não foram abertas.'}));document.querySelectorAll('.character-carousel,.reviews').forEach(track=>track.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();track.scrollBy({left:e.key==='ArrowRight'?200:-200,behavior:'smooth'})}}))})();
(()=>{document.querySelectorAll('.character-carousel,.reviews').forEach(el=>{let release;el.addEventListener('pointerdown',()=>{clearTimeout(release);el.classList.add('is-touching')});const resume=()=>{release=setTimeout(()=>el.classList.remove('is-touching'),8000)};el.addEventListener('pointerup',resume);el.addEventListener('pointercancel',resume)})})();
